class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        s1_cnt, s2_cnt, s2_idx, recall = 0, 0, 0, {}
        while s1_cnt < n1:
            s1_cnt += 1
            for char in s1:
                if char == s2[s2_idx]:
                    s2_idx += 1
                    if s2_idx == len(s2):
                        s2_idx, s2_cnt = 0, s2_cnt + 1
            if s2_idx in recall:
                prev_s1, prev_s2 = recall[s2_idx]
                num_cycles = (n1 - s1_cnt) // (s1_cnt - prev_s1)
                s1_cnt += num_cycles * (s1_cnt - prev_s1)
                s2_cnt += num_cycles * (s2_cnt - prev_s2)
                recall = {}
            else:
                recall[s2_idx] = (s1_cnt, s2_cnt)
        return s2_cnt // n2

