class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        res, c = [None] * n, 0
        for i in range(n):
            if res[i]: continue
            if c == 26: return ""
            for j in range(i, n):
                if lcp[i][j] > 0: res[j] = chr(97 + c)
            c += 1
        if None in res: return ""
        s, dp = "".join(res), [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
