class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        for i in range(n):
            if lcp[i][i] != n - i: return ""
            for j in range(n):
                if lcp[i][j] != lcp[j][i] or lcp[i][j] > n - max(i, j):
                    return ""

        ans, idx = [None] * n, 0
        for i in range(n):
            if ans[i] is None:
                if idx >= 26: return ""
                for j in range(i, n):
                    if lcp[i][j] > 0:
                        ans[j] = idx
                idx += 1

        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
