from typing import List

class Solution:
    def findAllRecipes(self, recepies: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        adj, indegree = defaultdict(list), defaultdict(int)
        for r, ings in zip(recepies, ingredients):
            indegree[r] = len(ings)
            for ing in ings: adj[ing].append(r)
        q, res, r_set = deque(supplies), [], set(recepies)
        while q:
            u = q.popleft()
            if u in r_set: res.append(u)
            for v in adj[u]:
                indegree[v] -= 1
                if indegree[v] == 0: q.append(v)
        return res

