class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        s1_c, s2_c, i, dp = 0, 0, 0, {}
        while s1_c < n1:
            s1_c += 1
            for c in s1:
                if c == s2[i]:
                    i += 1
                    if i == len(s2):
                        i, s2_c = 0, s2_c + 1
            if i in dp:
                p1, p2 = dp[i]
                num = (n1 - s1_c) // (s1_c - p1)
                s1_c += num * (s1_c - p1)
                s2_c += num * (s2_c - p2)
                dp = {}
            else:
                dp[i] = (s1_c, s2_c)
        return s2_c // n2

