from typing import List

class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        win, ans = [], []
        for i, x in enumerate(nums):
            bisect.insort(win, x)
            if len(win) > k:
                win.pop(bisect.bisect_left(win, nums[i - k]))
            if len(win) == k:
                m = k // 2
                ans.append(float(win[m]) if k % 2 else (win[m - 1] + win[m]) / 2.0)
        return ans

