class Solution:
    def splitListToParts(self, head: Optional[ListNode], k: int) -> List[Optional[ListNode]]:
        length, ptr = 0, head
        while ptr:
            length += 1
            ptr = ptr.next
        size, extra = divmod(length, k)
        l, curr = [], head
        for i in range(k):
            l.append(curr)
            for _ in range(size + (1 if i < extra else 0) - 1):
                if curr: curr = curr.next
            if curr:
                temp = curr.next
                curr.next = None
                curr = temp
        return l

