class Solution:
    def numPermsDISequence(self, s: str) -> int:
        n, mem, MOD = len(s), {}, 10**9 + 7
        def dfs(i, val):
            if i == n: return 1
            if (i, val) in mem: return mem[i, val]
            p = 0
            if s[i] == "D":
                for nv in range(val):
                    p = (p + dfs(i + 1, nv)) % MOD
            else:
                for nv in range(val, n - i):
                    p = (p + dfs(i + 1, nv)) % MOD
            mem[i, val] = p
            return p
        return sum(dfs(0, j) for j in range(n + 1)) % MOD

