class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        res, cur = [], []
        def backtrack(i):
            if i == len(s):
                if len(cur) == 4: res.append(".".join(cur))
                return
            if len(cur) == 4: return
            if s[i] == '0':
                cur.append('0'); backtrack(i + 1); cur.pop()
                return
            for l in range(1, 4):
                if i + l <= len(s) and int(s[i:i+l]) <= 255:
                    cur.append(s[i:i+l]); backtrack(i + l); cur.pop()
        backtrack(0)
        return res

class Solution:
    def smallestString(self, s: str) -> str:
        r, i, n = list(s), 0, len(s)
        while i < n and r[i] == 'a': i += 1
        if i == n: r[-1] = 'z'
        while i < n and r[i] != 'a':
            r[i] = chr(ord(r[i]) - 1)
            i += 1
        return "".join(r)

