class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not all(c in s1 for c in s2): return 0
        rec, track, ct, start = [0], {0: 0}, 0, 0
        while True:
            for char in s2:
                ptr = s1.find(char, start)
                if ptr == -1:
                    ct, ptr = ct + 1, s1.find(char)
                start = ptr + 1
            rec.append(ct + 1)
            if rec[-1] > n1: return (len(rec) - 2) // n2
            if start in track:
                pre = track[start]
                c1, c2 = rec[-1] - rec[pre], (len(rec) - 1) - pre
                res = pre + (n1 - rec[pre]) // c1 * c2
                rem = (n1 - rec[pre]) % c1
                for i in range(pre + 1, len(rec)):
                    if rec[i] - rec[pre] <= rem: res += 1
                return res // n2
            track[start] = len(rec) - 1

