    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        s1_cnt, s2_cnt, i, history = 0, 0, 0, {}
        while s1_cnt < n1:
            s1_cnt += 1
            for char in s1:
                if char == s2[i]:
                    i += 1
                    if i == len(s2):
                        s2_cnt += 1
                        i = 0
            if i in history:
                p_s1, p_s2 = history[i]
                num = (n1 - s1_cnt) // (s1_cnt - p_s1)
                s1_cnt += num * (s1_cnt - p_s1)
                s2_cnt += num * (s2_cnt - p_s2)
                history = {}
            else:
                history[i] = (s1_cnt, s2_cnt)
        return s2_cnt // n2

