from typing import List

class Solution:
    def maxPower(self, stations: List[int], r: int, k: int) -> int:
        n = len(stations)
        def check(target):
            rem, add, curr = k, [0] * n, sum(stations[:r+1])
            for i in range(n):
                if curr < target:
                    diff = target - curr
                    if diff > rem: return False
                    rem, add[min(i + r, n - 1)], curr = rem - diff, add[min(i + r, n - 1)] + diff, target
                if i + 1 < n:
                    if i + r + 1 < n: curr += stations[i + r + 1]
                    if i - r >= 0: curr -= stations[i - r] + add[i - r]
            return True
        low, high, ans = 0, sum(stations) + k, 0
        while low <= high:
            mid = (low + high) // 2
            if check(mid): ans, low = mid, mid + 1
            else: high = mid - 1
        return ans

