from functools import lru_cache

class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        @lru_cache(None)
        def dp(i, k, prev, ct):
            if k < 0: return 101
            if i == len(s): return 0

            # Option 1: Delete s[i]
            res = dp(i + 1, k - 1, prev, ct)

            # Option 2: Keep s[i]
            if s[i] == prev:
                res = min(res, dp(i + 1, k, prev, ct + 1) + (1 if ct in [1, 9, 99] else 0))
            else:
                res = min(res, dp(i + 1, k, s[i], 1) + 1)
            return res

        return dp(0, k, "", 0)

