class Solution:
    def numPermsDISequence(self, s: str) -> int:
        n, mem, mod = len(s), {}, 10**9 + 7
        def dfs(i, val):
            if i == n: return 1
            if (i, val) in mem: return mem[(i, val)]
            res = 0
            if s[i] == 'D':
                for k in range(val):
                    res = (res + dfs(i + 1, k)) % mod
            else:
                for k in range(val, n - i):
                    res = (res + dfs(i + 1, k)) % mod
            mem[(i, val)] = res
            return res
        return sum(dfs(0, j) for j in range(n + 1)) % mod

