from functools import lru_cache
from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        R, C = len(pizza), len(pizza[0])
        s = [[0] * (C + 1) for _ in range(R + 1)]
        for r in range(R - 1, -1, -1):
            for c in range(C - 1, -1, -1):
                s[r][c] = (pizza[r][c] == 'A') + s[r+1][c] + s[r][c+1] - s[r+1][c+1]

        @lru_cache(None)
        def dp(rem, r, c):
            if s[r][c] < rem: return 0
            if rem == 1: return 1
            res = 0
            for nr in range(r + 1, R):
                if s[r][c] > s[nr][c]:
                    res = (res + dp(rem - 1, nr, c)) % 1000000007
            for nc in range(c + 1, C):
                if s[r][c] > s[r][nc]:
                    res = (res + dp(rem - 1, r, nc)) % 1000000007
            return res

        return dp(k, 0, 0)

