class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        s2_set = set(s2)
        if not s2_set.issubset(set(s1)): return 0
        s1 = "".join(c for c in s1 if c in s2_set)
        s1_cnt = s2_cnt = i = 0
        history = {}
        while s1_cnt < n1:
            s1_cnt += 1
            for char in s1:
                if char == s2[i]:
                    i += 1
                    if i == len(s2): i, s2_cnt = 0, s2_cnt + 1
            if i in history:
                prev_s1, prev_s2 = history[i]
                delta_s1, delta_s2 = s1_cnt - prev_s1, s2_cnt - prev_s2
                num_cycles = (n1 - s1_cnt) // delta_s1
                s1_cnt += num_cycles * delta_s1
                s2_cnt += num_cycles * delta_s2
                history = {}
            else: history[i] = (s1_cnt, s2_cnt)
        return s2_cnt // n2

