class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        s1_cnt, s2_cnt, idx, recall = 0, 0, 0, {}
        while s1_cnt < n1:
            s1_cnt += 1
            for char in s1:
                if char == s2[idx]:
                    idx += 1
                    if idx == len(s2):
                        s2_cnt += 1
                        idx = 0
            if idx in recall:
                pre_s1, pre_s2 = recall[idx]
                num = (n1 - s1_cnt) // (s1_cnt - pre_s1)
                s1_cnt += num * (s1_cnt - pre_s1)
                s2_cnt += num * (s2_cnt - pre_s2)
                recall = {}
            else:
                recall[idx] = (s1_cnt, s2_cnt)
        return s2_cnt // n2

