class Solution:
    def numPermsDISequence(self, s: str) -> int:
        n, MOD = len(s), 10**9 + 7
        mem = {}
        def dfs(i, j):
            if i == n: return 1
            if (i, j) in mem: return mem[i, j]
            res = 0
            if s[i] == 'I':
                for k in range(j, n - i):
                    res = (res + dfs(i + 1, k)) % MOD
            else:
                for k in range(j):
                    res = (res + dfs(i + 1, k)) % MOD
            mem[i, j] = res
            return res
        return sum(dfs(0, j) for j in range(n + 1)) % MOD

