    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        s1_cnt, s2_cnt, index, recall = 0, 0, 0, {}
        while s1_cnt < n1:
            s1_cnt += 1
            for char in s1:
                if char == s2[index]:
                    index += 1
                    if index == len(s2):
                        s2_cnt += 1
                        index = 0
            if index in recall:
                s1_p, s2_p = recall[index]
                q, r = divmod(n1 - s1_p, s1_cnt - s1_p)
                s2_cnt = s2_p + q * (s2_cnt - s2_p)
                for _ in range(r):
                    for char in s1:
                        if char == s2[index]:
                            index += 1
                            if index == len(s2):
                                s2_cnt += 1
                                index = 0
                return s2_cnt // n2
            recall[index] = (s1_cnt, s2_cnt)
