class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        @lru_cache(None)
        def dp(i, k):
            if k < 0: return 101
            if i == len(s): return 0
            res = dp(i + 1, k - 1)
            c, d = 0, 0
            for j in range(i, len(s)):
                if s[j] == s[i]: c += 1
                else: d += 1
                if d > k: break
                ln = 1 if c == 1 else (2 if c < 10 else (3 if c < 100 else 4))
                res = min(res, ln + dp(j + 1, k - d))
            return res
        return dp(0, k)

